const diagnosis = (id: string) => { const value = diseases.find((item) => item.id === id); if (!value) throw new Error(`Unknown nephrology diagnosis: ${id}`); return value; };

const genericNegative = [
"نه، چنین چیزی نداشته‌ام.",
"خیر، موردی از این نظر متوجه نشده‌ام.",
"نه، سابقه مشخصی از این مشکل ندارم.",
"خیر، این علامت را تجربه نکرده‌ام.",
];

function historyAnswer(seed: CaseSeed, questionIndex: number): string {
  const text = (() => {
    const q = questionIndex; const p = seed.phenotype;
    return historyAnswersByCase[seed.id]?.[q] ?? genericNegative[(seed.id + q) % genericNegative.length];
  })();
  return text;
}

