const history = (seed: CaseSeed): CaseHint[] => nephrologyQuestionBank.map((question, index) => ({ id: `nephro-${seed.id}-h${index + 1}`, sourceId: question.id, label: question.text, content: historyAnswer(seed, index + 1) }));

function physicalExam(seed: CaseSeed): CaseHint[] {
  return nephrologyPhysicalExamBank.map((item, index) => ({ id: `nephro-${seed.id}-pe${index + 1}`, sourceId: item.id, label: item.title, content: physicalFindingsByCase[seed.phenotype]?.[index] ?? item.description }));
}

