function investigations_for_runtime(phenotype: string): Investigation[] {
  return (investigationNamesByPhenotype[phenotype] ?? ["Serum Creatinine", "Urinalysis", "Renal Ultrasound"]).map((name, index) => ({
    id: `investigation-${phenotype}-${index + 1}`,
    sourceId: investigationIdByName[name],
    name,
    category: nephrologyInvestigationBank.find((item) => item.id === investigationIdByName[name])?.category ?? "renal_function",
    findings: [{ label: "یافته", value: investigationFindingsByPhenotype[phenotype]?.[name] ?? "یافته متناسب با سناریوی کیس." }],
    relevance: "high",
  }));
}

