function reviewQuestions(seed: CaseSeed) {
  const candidates = (candidateSets[seed.phenotype] ?? [seed.diagnosisId]).slice(0, 4);
  while (candidates.length < 3) candidates.push(seed.diagnosisId);
  const opts = [seed.diagnosisId, ...candidates.filter((id) => id !== seed.diagnosisId)].slice(0, 4);
  return [{ id: `nephro-${seed.id}-review-1`, category: "diagnosis" as const, question: "کدام تشخیص با مجموع شرح حال، معاینه و بررسی‌های این کیس بیشترین تطابق را دارد؟", options: opts.map((id, index) => ({ id: `opt-${index + 1}`, text: diagnosis(id).name })), correctOptionId: "opt-1", explanation: `تشخیص نهایی این کیس ${diagnosis(seed.diagnosisId).name} است و الگوی شرح حال، معاینه و بررسی‌ها با آن سازگار است.` }];
}

export const nephrologyCases: Case[] = seeds.map((seed) => ({
  id: `nephro-${String(seed.id).padStart(3, "0")}`,
  title: seed.title,
  course: "nephrology",
  tags: seed.tags,
  difficulty: seed.difficulty,
  patient: { age: seed.age, sex: seed.sex },
  presentation: seed.presentation,
  stages: [
    { id: `nephro-${seed.id}-history`, type: "history", title: "شرح حال", hints: history(seed) },
    { id: `nephro-${seed.id}-physical`, type: "physical-exam", title: "معاینه فیزیکی", hints: physicalExam(seed) },
    { id: `nephro-${seed.id}-investigation`, type: "investigation", title: "بررسی‌های تشخیصی", investigations: investigationFindings(seed) },
  ],
  diagnosis: diagnosis(seed.diagnosisId),
  candidateDiagnosisIds: (candidateSets[seed.phenotype] ?? [seed.diagnosisId]).slice(0, 5).includes(seed.diagnosisId) ? (candidateSets[seed.phenotype] ?? [seed.diagnosisId]).slice(0, 5) : [seed.diagnosisId, ...(candidateSets[seed.phenotype] ?? []).filter((id) => id !== seed.diagnosisId)].slice(0, 5),
  reviewQuestions: reviewQuestions(seed),
}));

const validationErrors = nephrologyCases.flatMap((caseData) => validateNephrologyCases([caseData]));
if (validationErrors.length > 0) { throw new Error(`Nephrology case data integrity check failed:\n${validationErrors.map((e) => `${e.caseId}: ${e.code} — ${e.message}`).join("\n")}`); }
